<script>window.addEventListener('DOMContentLoaded',()=>setTimeout(()=>{if(document.documentElement.lang!=='km')return;const reportDate=@json($filters['report_date'] ?? now()->format('Y-m-d')),locationKh=@json($enrollments->first()?->campus?->campus_name_kh ?? $campus?->campus_name_kh ?? ''),digits=value=>String(value).replace(/[0-9]/g,d=>'០១២៣៤៥៦៧៨៩'[d]),weekdays=['អាទិត្យ','ចន្ទ','អង្គារ','ពុធ','ព្រហស្បតិ៍','សុក្រ','សៅរ៍'],months=['មករា','កុម្ភៈ','មីនា','មេសា','ឧសភា','មិថុនា','កក្កដា','សីហា','កញ្ញា','តុលា','វិច្ឆិកា','ធ្នូ'],date=new Date(reportDate+'T00:00:00'),day=digits(date.getDate()),year=date.getFullYear(),yearKh=digits(year),month=months[date.getMonth()]||'';document.querySelectorAll('.print-office-footer').forEach(item=>item.remove());document.querySelectorAll('.a4-page .report-table').forEach(table=>{const footer=document.createElement('div');footer.className='moeys-date-footer';let firstLine,secondLine;if(reportDate==='2026-08-24'){firstLine='ថ្ងៃចន្ទ ១១កើត ខែស្រាពណ៍ ឆ្នាំមមី អដ្ឋស័ក ព.ស.២៥៧០';secondLine=`${locationKh} ថ្ងៃទី${day} ខែ${month} ឆ្នាំ${yearKh}`}else{firstLine=`ថ្ងៃ${weekdays[date.getDay()]} ព.ស.${digits(year+544)}`;secondLine=`${locationKh} ថ្ងៃទី${day} ខែ${month} ឆ្នាំ${yearKh}`}footer.innerHTML=`<div>${firstLine}</div><div>${secondLine}</div><div>នាយកសាលា</div>`;table.insertAdjacentElement('afterend',footer)})},60));</script><style>.moeys-date-footer{margin-top:12px;text-align:left;font-family:"Khmer OS Siemreap","Khmer OS Siem Reap",sans-serif;font-size:12px;line-height:1.6}.moeys-date-footer div{margin:0}</style>
