<script>
window.addEventListener('load', () => setTimeout(() => {
    if (document.documentElement.lang !== 'km' || typeof window.formatKhmerLunarDate !== 'function') return;
    const reportDate = @json($filters['report_date'] ?? now()->format('Y-m-d'));
    const locationKh = window.resolveMoeysLocation(
        @json($enrollments->first()?->campus?->campus_name_kh ?? $campus?->campus_name_kh ?? ''),
        @json($enrollments->first()?->campus?->address ?? $campus?->address ?? '')
    );
    const lunarDate = window.formatKhmerLunarDate(reportDate);
    const solarDate = window.formatKhmerSolarDate(reportDate, locationKh);
    document.querySelectorAll('.moeys-date-footer').forEach((footer) => {
        footer.innerHTML = `<div>${lunarDate}</div><div>${solarDate}</div><div>នាយកសាលា</div>`;
    });
}, 120));
</script>
@endif
